class Test(TestCase):
    @staticmethod
    def _z3_unsat(expr) -> bool:
        s = Solver()
        s.add(expr)
        return s.check() == unsat

    @staticmethod
    def _z3_and_terms(expr):
        if is_and(expr):
            terms = []
            for c in expr.children():
                terms.extend(Test._z3_and_terms(c))
            return terms
        return [expr]

    def _z3_simplify_under_assumption_by_literal_pruning(self, base, guard):
        terms = self._z3_and_terms(guard)
        if len(terms) == 0:
            return BoolVal(True)

        current = list(terms)
        i = 0
        while i < len(current):
            trial_terms = current[:i] + current[i + 1 :]
            trial = And(*trial_terms) if len(trial_terms) > 0 else BoolVal(True)
            current_f = And(*current) if len(current) > 0 else BoolVal(True)
            if self._z3_unsat(And(base, Xor(current_f, trial))):
                current = trial_terms
            else:
                i += 1

        return And(*current) if len(current) > 0 else BoolVal(True)

    def _z3_simplify_under_assumption_ctx_simplify(self, base, guard):
        # Ask Z3 to simplify in the context where `base` is present.
        goal = Goal()
        goal.add(base, guard)
        subgoal = Tactic("ctx-simplify")(goal)[0]

        kept = []
        for f in subgoal:
            # Drop formulas already guaranteed by the base context.
            if self._z3_unsat(And(base, ~f)):
                continue
            kept.append(f)

        candidate = And(*kept) if len(kept) > 0 else BoolVal(True)
        self.assertTrue(self._z3_unsat(And(base, Xor(guard, candidate))))
        return candidate

    def _z3_simplify_under_assumption_consequences(self, base, guard):
        # Use z3 consequences to keep only guard conjuncts not already forced by base.
        terms = self._z3_and_terms(simplify(guard))
        if len(terms) == 0:
            return BoolVal(True)

        s = Solver()
        s.add(base, guard)
        status, consequences = s.consequences([], terms)
        self.assertEqual(status, sat)

        implied_terms = set()
        for imp in consequences:
            if imp.num_args() == 2 and is_true(imp.arg(0)):
                implied_terms.add(imp.arg(1))

        kept = []
        for t in terms:
            # Keep conservative behavior if Z3 didn't report the queried term.
            if t not in implied_terms:
                kept.append(t)
                continue
            # Drop only conjuncts already implied by base.
            if self._z3_unsat(And(base, ~t)):
                continue
            kept.append(t)

        candidate = And(*kept) if len(kept) > 0 else BoolVal(True)
        self.assertTrue(self._z3_unsat(And(base, Xor(guard, candidate))))
        return candidate

    def test_z3_simplify_under_assumption_literal_pruning(self):
        x, y = Ints("x y")
        base = And(y >= 2, x >= y)
        guard = And(y >= 2, x >= y, x >= 0)

        simplified_guard = self._z3_simplify_under_assumption_by_literal_pruning(
            base, guard
        )

        self.assertTrue(self._z3_unsat(And(base, Xor(guard, simplified_guard))))
        self.assertTrue(str(simplified_guard) == "True")

    def test_z3_simplify_under_assumption_d1_or_d2_and_c_to_c(self):
        d1, d2, c = Bools("d1 d2 c")
        base = d1 | d1
        guard = And(d1 | d2, c)

        simplified_guard = self._z3_simplify_under_assumption_ctx_simplify(base, guard)

        self.assertTrue(self._z3_unsat(And(base, Xor(guard, simplified_guard))))
        self.assertEqual(str(simplify(simplified_guard)), "c")

    def test_z3_simplify_under_assumption_consequences_d1_or_d2_and_c_to_c(self):
        d1, d2, c = Bools("d1 d2 c")
        base = d1 | d1
        guard = And(d1 | d2, c)

        simplified_guard = self._z3_simplify_under_assumption_consequences(base, guard)

        self.assertTrue(self._z3_unsat(And(base, Xor(guard, simplified_guard))))
        self.assertEqual(str(simplify(simplified_guard)), "c")

