    def test_simpl(self):
        c = string_to_prop("d1_A = d1 & d2_A = d2")
        A = string_to_prop("(d1_A | d2_A)")
        B = string_to_prop("(d1 | d2) & c")

        symbol_table = {
            "d1_A": BOOLEAN,
            "d2_A": BOOLEAN,
            "d1": BOOLEAN,
            "d2": BOOLEAN,
            "c": BOOLEAN,
        }

        f = conjunct(c, conjunct(A, B))
        vars = [Symbol("d1_A"), Symbol("d2_A")]
        qe_res = quantifier_elimination(Exists(vars, f.to_smt(symbol_table)[0]))
        xx = serialize(qe_res)
        print(str(xx))

    def test_dnf(self):
        input = conjunct(Variable("p"), Variable("q"))
        res = dnf(input)
        self.assertTrue(res == input)

    def test_dnf_0(self):
        input = disjunct(Variable("p"), Variable("q"))
        res = dnf(conjunct(input, input))
        self.assertTrue(len(str(res)) == len(str(input)))

    def test_dnf_1(self):
        input = disjunct(Variable("p"), Variable("q"))
        res = dnf(conjunct(input, neg(input)))
        self.assertTrue(isinstance(res, Value) and res.is_false())

